+const DIVSTEPS: u32 = 62;
+const DIVSTEPS_MASK: u64 = (1 << DIVSTEPS) - 1;
+
+/// A signed integer `limbs + high * 2^256`.
+#[derive(Clone, Copy)]
+struct Signed {
+    limbs: [u64; 4],
+    high: i64,
+}
+
+/// Runs 62 divsteps (Bernstein--Yang, variable time) on the low words of
+/// `f` and `g`, returning the new `delta` and the transition matrix.
+#[inline(always)]
+fn divsteps(mut delta: i32, mut f: u64, mut g: u64) -> (i32, [[i64; 2]; 2]) {
+    let (mut u, mut v, mut q, mut r) = (1i64, 0i64, 0i64, 1i64);
+    let mut remaining = DIVSTEPS;
+    while remaining != 0 {
+        let zeros = g.trailing_zeros().min(remaining);
+        if zeros != 0 {
+            g >>= zeros;
+            u <<= zeros;
+            v <<= zeros;
+            delta += zeros as i32;
+            remaining -= zeros;
+            if remaining == 0 {
+                break;
+            }
+        }
+        remaining -= 1;
+        if delta > 0 {
+            delta = 1 - delta;
+            (f, g) = (g, g.wrapping_sub(f) >> 1);
+            (u, v, q, r) = (2 * q, 2 * r, q - u, r - v);
+        } else {
+            delta += 1;
+            g = g.wrapping_add(f) >> 1;
+            q += u;
+            r += v;
+            u *= 2;
+            v *= 2;
+        }
+    }
+    (delta, [[u, v], [q, r]])
+}
+
+/// Divides `limbs + high * 2^256` by `2^62`; the low 62 bits must be zero.
+#[inline(always)]
+fn shift_divsteps(limbs: [u64; 4], high: i128) -> Signed {
+    Signed {
+        limbs: [
+            (limbs[0] >> DIVSTEPS) | (limbs[1] << (64 - DIVSTEPS)),
+            (limbs[1] >> DIVSTEPS) | (limbs[2] << (64 - DIVSTEPS)),
+            (limbs[2] >> DIVSTEPS) | (limbs[3] << (64 - DIVSTEPS)),
+            (limbs[3] >> DIVSTEPS) | ((high as u64) << (64 - DIVSTEPS)),
+        ],
+        high: (high >> DIVSTEPS) as i64,
+    }
+}
+
+/// `(u * f + v * g) / 2^62`, exact for the matrices produced by `divsteps`.
+#[inline(always)]
+fn update_integer(f: Signed, g: Signed, [u, v]: [i64; 2]) -> Signed {
+    let mut limbs = [0u64; 4];
+    let mut carry = 0i128;
+    for (i, word) in limbs.iter_mut().enumerate() {
+        let sum = u as i128 * f.limbs[i] as i128 + v as i128 * g.limbs[i] as i128 + carry;
+        *word = sum as u64;
+        carry = sum >> 64;
+    }
+    shift_divsteps(
+        limbs,
+        carry + u as i128 * f.high as i128 + v as i128 * g.high as i128,
+    )
+}
+
+/// `(u * d + v * e) / 2^62 mod p` for `d, e < p`, returned in `[0, p)`.
+#[inline(always)]
+fn update_coefficient(d: [u64; 4], e: [u64; 4], [u, v]: [i64; 2]) -> [u64; 4] {
+    // -p^-1 = 1 (mod 2^64), so adding `low mod 2^62` multiples of p makes
+    // the sum divisible by 2^62.
+    let correction = d[0]
+        .wrapping_mul(u as u64)
+        .wrapping_add(e[0].wrapping_mul(v as u64))
+        & DIVSTEPS_MASK;
+    let mut limbs = [0u64; 4];
+    let mut carry = 0i128;
+    for (i, word) in limbs.iter_mut().enumerate() {
+        let sum = u as i128 * d[i] as i128
+            + v as i128 * e[i] as i128
+            + correction as i128 * MODULUS[i] as i128
+            + carry;
+        *word = sum as u64;
+        carry = sum >> 64;
+    }
+    // The result lies in (-p, 2p).
+    let result = shift_divsteps(limbs, carry);
+    if result.high < 0 {
+        add_limbs(result.limbs, MODULUS).0
+    } else {
+        let (reduced, borrow) = sub_limbs(result.limbs, MODULUS);
+        if result.high != 0 || borrow == 0 {
+            reduced
+        } else {
+            result.limbs
+        }
+    }
+}
+
+/// Returns `value^-1 * seed mod p` for a nonzero `value < p` and `seed < p`,
+/// in variable time.
+fn invert_canonical(value: [u64; 4], seed: [u64; 4]) -> [u64; 4] {
+    // Invariants: value * d = f * seed and value * e = g * seed (mod p).
+    let mut f = Signed {
+        limbs: MODULUS,
+        high: 0,
+    };
+    let mut g = Signed {
+        limbs: value,
+        high: 0,
+    };
+    let (mut d, mut e) = ([0u64; 4], seed);
+    let mut delta = 1;
+
+    while g.high != 0 || g.limbs != [0; 4] {
+        let (next_delta, matrix) = divsteps(delta, f.limbs[0], g.limbs[0]);
+        delta = next_delta;
+        (f, g) = (
+            update_integer(f, g, matrix[0]),
+            update_integer(f, g, matrix[1]),
+        );
+        (d, e) = (
+            update_coefficient(d, e, matrix[0]),
+            update_coefficient(d, e, matrix[1]),
+        );
+    }
+
+    // f = +/-1 at termination, and d is nonzero.
+    if f.high < 0 {
+        sub_limbs(MODULUS, d).0
+    } else {
+        d
+    }
+}

